{"source": "def investigate(context, acquire):
    events = acquire("events")
    seen = set()
    total = 0
    for event in events:
        event_id = event["event_id"]
        if event_id not in seen:
            seen.add(event_id)
            total = total + event["work"]
    return {"findings": [], "unresolved": [], "ratio": total}" , "scope": "Sums work once per unique event_id across acquired event records.", "lesson": "Deduplicate by event_id before summing work to avoid double counting repeated deliveries."}
